#include <stdio.h>
#include <stdlib.h>

int dominantIndex(int* nums, int numsSize) {
    int maxIdx = 0;
    for (int i = 1; i < numsSize; ++i) {
        if (nums[i] > nums[maxIdx]) maxIdx = i;
    }
    int maximum = nums[maxIdx];
    for (int i = 0; i < numsSize; ++i) {
        if (i != maxIdx && maximum < 2 * nums[i]) return -1;
    }
    return maxIdx;
}

